<?php namespace App\Filament\Resources\StudentSupportCaseResource\RelationManagers;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\RelationManagers\RelationManager;use Filament\Resources\Table;use Filament\Tables;class ActionsRelationManager extends RelationManager{protected static string $relationship='actions';protected static ?string $title='История работы';public static function form(Form $f):Form{return $f->schema([Forms\Components\Select::make('action_type')->label('Действие')->options(['conversation'=>'Беседа','parent_contact'=>'Контакт с родителями','referral'=>'Направление','meeting'=>'Встреча','monitoring'=>'Мониторинг','document'=>'Документ','other'=>'Другое'])->required(),Forms\Components\Textarea::make('note')->label('Запись')->required()]);}public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('acted_at')->label('Дата')->dateTime('d.m.Y H:i'),Tables\Columns\BadgeColumn::make('action_type')->label('Тип'),Tables\Columns\TextColumn::make('note')->label('Запись')->limit(100)])->headerActions([Tables\Actions\CreateAction::make()->label('Добавить запись')->mutateFormDataUsing(fn($d)=>$d+['acted_at'=>now(),'user_id'=>auth()->id()])]);}}